from research_helpers import *
a=ev('https://www.veeva.com/products/veeva-clinical-platform/','Current manufacturer platform catalogue identifies individual clinical research applications. General commercial CRM and an AI agent do not become biological products or physical robots by association.')
b=ev('https://www.veeva.com/products/veeva-edc/','Current product page confirms marketed clinical trial data collection, review and processing application.')
c=ev('https://www.veeva.com/products/clinical-data-management/','Current product catalogue identifies DQS clinical data quality and aggregation application.')
d=ev('https://cdmshelp.veeva.com/ko/lr/rn/general-releases/26r2/whats-new/','Manufacturer 26R2 release notes explicitly identify CDB rebranding to DQS, so these are one product identity, not two.')
e=ev('https://www.veeva.com/products/veeva-ecoa/','Current product page identifies eCOA questionnaires from patients, clinicians and caregivers; ePRO/eClinRO are collection modes, not assumed separate products.')
f=ev('https://www.veeva.com/products/veeva-rtsm/','Current product page identifies clinical trial subject randomization, kit assignments and trial supply management application.')
products=[p('Veeva EDC','Clinical research electronic data capture application for study design, patient data collection, review and closeout.',b,'commercial',typ='technology',sub='research_tools',aliases=['Veeva Vault EDC']),p('Veeva DQS','Clinical research data quality system for aggregation, cleaning and transformation of trial data; renamed from Veeva CDB in 26R2.',c,'commercial',typ='technology',sub='research_tools',aliases=['Veeva CDB'],evidence=[c,d]),p('Veeva eCOA','Electronic clinical outcome assessment research application for patient, clinician and caregiver questionnaires.',e,'commercial',typ='technology',sub='research_tools'),p('Veeva RTSM','Clinical trial randomization and investigational supply management research application.',f,'commercial',typ='technology',sub='research_tools'),p('Veeva CTMS','Clinical trial management and study monitoring research application.',a,'commercial',typ='technology',sub='research_tools')]
co=company('Veeva Systems Inc.',products,[a,b,c,d,e,f],'Initial direct clinical research tools recorded under biotech research tools as software technologies. DQS and former CDB share one identity. No medicines attributed from customer list; AI software not physical robotics. Partial: remaining clinical tools, eSource availability, historical acquired platforms, clinical safety/analysis products and research-specific product boundaries require review. Suite names not duplicated over individual applications.',status='partial')
